<?php
/**
 * Lesson quizzes: a few multiple-choice questions at the end of each lesson.
 *
 * Questions live in data/quizzes/<path-slug>.php (generated by
 * tools/build_quizzes.py from content/quizzes/*.md), keyed by lesson slug, so
 * updating the theme updates quizzes without re-importing lessons.
 *
 * @package VitalStack
 */

defined( 'ABSPATH' ) || exit;

const VITALSTACK_XP_QUIZ_PER_ANSWER = 2;
const VITALSTACK_XP_DAILY           = 15;

/**
 * All quizzes of one learning path: slug => list of questions.
 *
 * @param string $path_slug Learning path slug, e.g. "python".
 * @return array<string, array<int, array{q:string,o:string[],a:int,e:string}>>
 */
function vitalstack_path_quizzes( $path_slug ) {
	static $cache = array();
	$path_slug = sanitize_key( $path_slug );
	if ( ! isset( $cache[ $path_slug ] ) ) {
		$file                 = VITALSTACK_DIR . '/data/quizzes/' . $path_slug . '.php';
		$cache[ $path_slug ] = ( $path_slug && file_exists( $file ) ) ? (array) include $file : array();
	}
	return $cache[ $path_slug ];
}

/**
 * Questions for one lesson, or an empty array.
 */
function vitalstack_lesson_quiz_questions( $post = null ) {
	$post = get_post( $post );
	if ( ! $post || 'tutorials' !== $post->post_type ) {
		return array();
	}
	$path = vitalstack_tutorial_path( $post->ID );
	if ( ! $path ) {
		return array();
	}
	$all = vitalstack_path_quizzes( $path->slug );
	return isset( $all[ $post->post_name ] ) ? $all[ $post->post_name ] : array();
}

/**
 * `code` in quiz text → <code>, everything else escaped.
 */
function vitalstack_quiz_text( $text ) {
	$out = esc_html( $text );
	return preg_replace( '/`([^`]+)`/', '<code>$1</code>', $out );
}

/**
 * Markup for one question. Used by lesson quizzes and the daily challenge.
 */
function vitalstack_quiz_question_markup( $q, $n, $name ) {
	$out  = '<fieldset class="quiz-q" data-answer="' . (int) $q['a'] . '">';
	$out .= '<legend><span class="quiz-n">' . (int) $n . '</span>' . vitalstack_quiz_text( $q['q'] ) . '</legend>';
	$out .= '<div class="quiz-options">';
	foreach ( $q['o'] as $i => $opt ) {
		$out .= '<button type="button" class="quiz-opt" data-i="' . (int) $i . '" name="' . esc_attr( $name ) . '"><span class="quiz-letter">' . esc_html( chr( 65 + $i ) ) . '</span><span>' . vitalstack_quiz_text( $opt ) . '</span></button>';
	}
	$out .= '</div>';
	if ( ! empty( $q['e'] ) ) {
		$out .= '<p class="quiz-explain" hidden>' . vitalstack_quiz_text( $q['e'] ) . '</p>';
	}
	$out .= '</fieldset>';
	return $out;
}

/**
 * The quiz block shown at the end of a lesson.
 */
function vitalstack_lesson_quiz() {
	$questions = vitalstack_lesson_quiz_questions();
	if ( ! $questions ) {
		return;
	}
	$slug = get_post_field( 'post_name', get_the_ID() );
	?>
	<section class="quiz" data-quiz="<?php echo esc_attr( $slug ); ?>" aria-labelledby="quiz-title">
		<div class="quiz-head">
			<div class="quiz-bot" aria-hidden="true"><?php echo vitalstack_mascot( 'think', 64, '', 'bugsy' ); // phpcs:ignore WordPress.Security.EscapeOutput -- static SVG ?></div>
			<div>
				<h2 id="quiz-title" class="quiz-title"><?php esc_html_e( 'Quick quiz', 'vitalstack' ); ?></h2>
				<p class="quiz-sub">
					<?php
					/* translators: 1: number of questions, 2: XP per correct answer */
					echo esc_html( sprintf( __( '%1$d questions. Check what stuck and earn %2$d XP for each right answer.', 'vitalstack' ), count( $questions ), VITALSTACK_XP_QUIZ_PER_ANSWER ) );
					?>
				</p>
			</div>
		</div>
		<div class="quiz-body">
			<?php
			foreach ( $questions as $i => $q ) {
				echo vitalstack_quiz_question_markup( $q, $i + 1, 'q' . $i ); // phpcs:ignore WordPress.Security.EscapeOutput -- escaped inside
			}
			?>
		</div>
		<div class="quiz-result" hidden aria-live="polite">
			<p class="quiz-score"></p>
			<button type="button" class="btn btn-ghost btn-sm" data-quiz-retry><?php esc_html_e( 'Try again', 'vitalstack' ); ?></button>
		</div>
	</section>
	<?php
}

/**
 * Practice-problem structured data (schema.org Quiz) for lessons with a quiz.
 */
function vitalstack_quiz_schema() {
	if ( ! is_singular( 'tutorials' ) ) {
		return;
	}
	$questions = vitalstack_lesson_quiz_questions( get_queried_object() );
	if ( ! $questions ) {
		return;
	}
	$path  = vitalstack_tutorial_path( get_queried_object_id() );
	$parts = array();
	foreach ( $questions as $q ) {
		$answers = array();
		foreach ( $q['o'] as $i => $opt ) {
			$answers[] = array(
				'@type'    => 'Answer',
				'position' => $i,
				'text'     => wp_strip_all_tags( str_replace( '`', '', $opt ) ),
			);
		}
		$question = array(
			'@type'             => 'Question',
			'eduQuestionType'   => 'Multiple choice',
			'learningResourceType' => 'Practice problem',
			'name'              => wp_strip_all_tags( str_replace( '`', '', $q['q'] ) ),
			'text'              => wp_strip_all_tags( str_replace( '`', '', $q['q'] ) ),
			'suggestedAnswer'   => array_values( array_diff_key( $answers, array( $q['a'] => 1 ) ) ),
			'acceptedAnswer'    => $answers[ $q['a'] ],
		);
		if ( ! empty( $q['e'] ) ) {
			$question['acceptedAnswer']['answerExplanation'] = array(
				'@type' => 'Comment',
				'text'  => wp_strip_all_tags( str_replace( '`', '', $q['e'] ) ),
			);
		}
		$parts[] = $question;
	}
	$data = array(
		'@context'    => 'https://schema.org',
		'@type'       => 'Quiz',
		'name'        => get_the_title( get_queried_object() ) . ' – quiz',
		'about'       => array(
			'@type' => 'Thing',
			'name'  => $path ? $path->name : get_the_title( get_queried_object() ),
		),
		'educationalLevel' => 'beginner',
		'hasPart'     => $parts,
	);
	echo '<script type="application/ld+json">' . wp_json_encode( $data, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE ) . "</script>\n";
}
add_action( 'wp_head', 'vitalstack_quiz_schema', 20 );

/**
 * XP for quizzes and the daily challenge (hooked into the XP REST endpoint).
 *
 * @param int    $gained  XP already given by other types.
 * @param string $type    Activity type.
 * @param string $ref     Reference.
 * @param int    $score   Correct answers (quiz) or 1/0 (daily).
 * @param int    $user_id User.
 */
function vitalstack_quiz_xp( $gained, $type, $ref, $score, $user_id ) {
	if ( 'quiz' === $type && $ref ) {
		$max = 0;
		$post = get_page_by_path( $ref, OBJECT, 'tutorials' );
		if ( $post ) {
			$max = count( vitalstack_lesson_quiz_questions( $post ) );
		}
		$score = max( 0, min( $max, (int) $score ) );
		return $gained + vitalstack_xp_award( $user_id, $score * VITALSTACK_XP_QUIZ_PER_ANSWER, 'quiz:' . $ref );
	}
	if ( 'daily' === $type && (int) $score > 0 && vitalstack_xp_today() === $ref ) {
		return $gained + vitalstack_xp_award( $user_id, VITALSTACK_XP_DAILY, 'daily:' . $ref );
	}
	return $gained;
}
add_filter( 'vitalstack_xp_activity', 'vitalstack_quiz_xp', 10, 5 );
